/**
 * Per-window settings.
 *
 * Upstream stores these under one key per window type —
 * `EZConfiguration_InputFieldCellVisible_Window0_Key` and so on, generated by
 * `windowConfigurationKey(_:windowType:defaultValue:)` in
 * `WindowConfigurationKey.swift`. `showInputTextField(key:windowType:)` is the
 * single reader every window goes through (`Configuration+Extension.swift:74`),
 * and `EZLayoutManager` consults it before giving the input view any height.
 *
 * The port spells the same six keys out as flat settings fields, because the
 * JSON document is this port's own shape. This module is the one place that
 * maps a window kind onto them, so a window never indexes the settings object
 * with a hand-built field name.
 */

import type { Settings, WindowType } from "../types";

/** `WindowConfigurationKey` — the two switches each query window owns. */
export type WindowConfigurationKey = "inputField" | "selectLanguage";

const KEYS: Record<WindowType, Record<WindowConfigurationKey, keyof Settings>> = {
  main: {
    inputField: "inputFieldCellVisibleMain",
    selectLanguage: "selectLanguageCellVisibleMain",
  },
  mini: {
    inputField: "inputFieldCellVisibleMini",
    selectLanguage: "selectLanguageCellVisibleMini",
  },
  fixed: {
    inputField: "inputFieldCellVisibleFixed",
    selectLanguage: "selectLanguageCellVisibleFixed",
  },
};

/**
 * The stored value of one per-window switch.
 *
 * Missing settings — the first paint, or a document written before these keys
 * existed — read as `true`, which is the upstream default. A value that is not
 * a boolean is also treated as the default rather than as "off", so a corrupt
 * document cannot silently hide a window's input field.
 */
export function windowConfigurationValue(
  settings: Settings | null | undefined,
  kind: WindowType,
  key: WindowConfigurationKey,
): boolean {
  const field: keyof Settings | undefined = KEYS[kind]?.[key];
  if (!field) {
    return true;
  }
  const value = settings?.[field];
  return typeof value === "boolean" ? value : true;
}

/** Whether this window shows its query input field. */
export function showsInputField(
  settings: Settings | null | undefined,
  kind: WindowType,
): boolean {
  return windowConfigurationValue(settings, kind, "inputField");
}

/** Whether this window shows the `源语言 ⇄ 目标语言` row. */
export function showsLanguageBar(
  settings: Settings | null | undefined,
  kind: WindowType,
): boolean {
  return windowConfigurationValue(settings, kind, "selectLanguage");
}
